SCREEN_TYPES = ["СТЕНД", "БИОС", "БЕНЧ", "HWINFO", "ИГРА", "ИНФОГРАФИКА", "ТИТР", "ТАБЛИЦА", "МЕМ", "ГУСЬ", "АРХИВ"]
ALLOW = re.compile(r"9950X3D|B650(-A)?|X870E|CS2|R23|5070|CL\d+|LLC\d?|8000|6000|fps_max\s?\d|2:1|2×2|3×3|×4|\+2079|24/7|404|3:50|3:40|CCD0|10X|−25/−20|−30/−30/−25/−10|\+200|\d\s?(ядер|чиплет|секунд|сек)\b|в рекорд-режиме 16 277|кадра? \d+")

def expand(s): return re.sub(r"\{([A-Z0-9_]+)\}", lambda m: BANK.get(m.group(1), "<<%s>>" % m.group(1)), s)

def validate():
    errs = []
    for f in frames:
        g = S.get(f["id"])
        if not g: errs.append("кадр %d не размечен" % f["id"]); continue
        if g["screen"] not in SCREEN_TYPES: errs.append("кадр %d: screen вне словаря" % f["id"])
        blob = " ".join([g["see"], " ".join(g["titles"]), g["gfx"], g["meme"], g["pause"]])
        for ident in re.findall(r"\{([A-Z0-9_]+)\}", blob):
            if ident not in BANK: errs.append("кадр %d: нет в банке {%s}" % (f["id"], ident))
        st = ALLOW.sub("", re.sub(r"\{[A-Z0-9_]+\}", "", blob))
        nums = [n for n in re.findall(r"\d[\d\s,\.]*", st) if re.search(r"\d{2,}", n)]
        if nums: errs.append("кадр %d: сырые числа вне банка: %s" % (f["id"], nums[:6]))
        if "мировой рекорд" in blob.lower(): errs.append("кадр %d: «мировой рекорд»" % f["id"])
        if "!" in " ".join(g["titles"]): errs.append("кадр %d: восклицание в титре" % f["id"])
        if "<<" in expand(blob): errs.append("кадр %d: нераскрытый идентификатор" % f["id"])
    return errs

def render():
    L = ["# ДЕ-ЛИДЕР 3 · ВИЗУАЛЬНЫЙ СКРИНПЛЕЙ", "",
         "Таймлайн по тексту под запись: голос цифр не читает, все цифры живут в правой колонке и взяты из LIVE-таблицы. "
         "Темп речи откалиброван по реальному чтению (~15 минут на текст), паузы под музыку короткие, потому что инфографика идёт поверх речи. "
         "Общий хронометраж ~%s. Скелет разметки собран Гроком, досужен и дописан по кадрам; валидация цифр — кодом." % tc(TOTAL), "",
         "Цвета профилей на весь ролик: Сток серый · ПБО синий · Лок красный · Анлим чёрный/золотой. «Якорная панель» — угол экрана с четырьмя игровыми цифрами текущей ступени, живёт всю лестницу.", "",
         "| Тайм | Закадр (читается) | Экран | Титры · графика · пауза |", "|---|---|---|---|"]
    for f in frames:
        g = S[f["id"]]
        screen = "**%s.** %s" % (g["screen"], expand(g["see"]))
        if g["meme"]: screen += " *Мем: %s.*" % expand(g["meme"])
        right = ["ТИТР: «%s»" % expand(t_) for t_ in g["titles"]]
        if g["gfx"]: right.append("ГРАФИКА: " + expand(g["gfx"]))
        if f["pause"]: right.append("⏸ %dс под музыку: %s" % (f["pause"], expand(g["pause"]) or "скринкаст прогона"))
        L.append("| %s–%s | %s | %s | %s |" % (tc(f["t0"]), tc(f["t1"] + f["pause"]), f["vo"].replace("|", "/"), screen.replace("|", "/"), "<br>".join(right).replace("|", "/")))
    fid = {f["id"]: f for f in frames}
    L += ["", "## ГЛАВЫ YOUTUBE"]
    for cid, name in [(0, "Сварка и страх"), (1, "Правила стенда"), (4, "Матчасть и ловушки биоса"), (6, "Лестница на флагмане"), (17, "Та же лестница за четверть цены"), (25, "Ток, а не тепло"), (29, "Контра"), (34, "Мы проверили и себя"), (36, "Итоги")]:
        L.append("- %s — %s" % (tc(fid[cid]["t0"]), name))
    # шотлист графики для моушена
    L += ["", "## ШОТЛИСТ ГРАФИКИ (что собрать моушен-дизайнеру, по порядку появления)"]
    seen = []
    for f in frames:
        g = S[f["id"]]
        if g["gfx"]:
            seen.append("- **%s (кадр %d)** — %s" % (tc(f["t0"]), f["id"], expand(g["gfx"])))
    L += seen
    L += ["", "## ЗАПРЕТЫ НА ЭКРАН (из гейта честности)",
          "1. Частота и ватты ПБО обеих плат — не показывать. 2. Частота стока B650 рядом с Extreme — не ставить. 3. 48 579 всегда с повтором 48 189. "
          "4. Игры Extreme на анлиме на полном чипе — плашка «не мерено», не бар. 5. Ни слова «рекорд» у 48 880 — «личный потолок». "
          "6. Температура анлима против лока — с подписью про методику. 7. Никаких следов ИИ/агентов в титрах и описании.", ""]
    io.open(OUT_MD, "w", encoding="utf-8").write("\n".join(L) + "\n")

if __name__ == "__main__":
    errs = validate()
    print("кадров:", len(frames), "| речь ~%s + паузы = ~%s" % (tc(sum(len(p.split()) for p in paras) / WPS), tc(TOTAL)))
    print("валидация: %d ошибок" % len(errs))
    for e in errs: print("  -", e)
    if not errs:
        render(); print("md ->", OUT_MD)
    else:
        sys.exit(1)
